var spi = new SPI();
spi.setup({ sck: D31, mosi: D2 });
var g = require("ST7565").connect({ spi:spi, dc:D29, cs:D5, rst:D30 }, function() {
  g.clear();
  g.setRotation(0,1);
  g.setContrast(0.5, 3);
  g.drawString("Hello",0,0);
  g.drawLine(0, 10, g.getWidth(), 10);
  g.flip();
});

Graphics.prototype.setFontGShock36 = function(scale) {
  return(this.setFontCustom(atob(""),47, atob("AhgUFhcVFhgUFhYI"), 36 + (scale << 8)));
};

// not really "Euro", but a small, wide font for LCD like labels
Graphics.prototype.setFontEuro = function(scale) {
  return(this.setFontCustom(atob(""), 32, atob("BQAAAAAAAAAAAAAAAAAEBgoHCQkKCQkJCQkEAAAAAAcACgoKCgkICgoEBwoHCwoLCQsJCQkKCQ4KCQoAAg=="), 11 + (scale << 8)));
};

function clock() {
  let dt = new Date().toString();
  g.clear();
  g.drawLine(0, 10, 127, 10);
  g.drawLine(0, 53, 127, 53);
  g.setFont("Euro",1);
  g.setFontAlign(0,0);
  g.drawString(dt.substring(0,10).toUpperCase(), 63, 4);
  g.setFont("GShock36",1);
  let mk = dt.indexOf("2026")+5;
  g.drawString(dt.substring(mk, mk+5), 63, 32);
  g.flip();
}